"""! @brief 종료 확인된 실패를 보존하고 독립 손실 사례의 명시적 후속 실행을 지원한다."""

from copy import deepcopy
import time

from rfad.application.canonical import canonical_hash
from rfad.application.pcb_loss_study import assess
from rfad.application.radiation_study import require
from verify_openems_worker import call
from verify_ifa_convergence import execute_phase, save_report
from radiation_convergence.evidence import reference


def blocked_job(service, entry):
    """! @brief 소유 native의 확정 종료/슬롯 반환이 있는 실패만 후속 독립 실행에서 건너뛴다."""
    state = service.journal.read()
    for phase in ("analysis", "prepare"):
        task = entry.get("phases", {}).get(phase, {}).get("task")
        if task is None:
            continue
        job = state["jobs"].get(task["job_id"])
        require(job is not None, "원래 손실 연구 작업이 journal에 없습니다.")
        if job["state"] in {"failed", "cancelled", "interrupted"}:
            event = job["events"][-1]
            require(event.get("termination_confirmed") is True and not event.get("outcome_unknown", False)
                    and not job["solver"].get("resource_reserved"), "실패한 native의 종료/슬롯 반환이 확인되지 않았습니다.")
            return {"job_id": job["job_id"], "run_id": job["run_id"], "state": job["state"], "terminal_event": deepcopy(event)}
    return None


def execute_case(service, report, path, entry, subject):
    """! @brief 같은 요청 키를 재조회하며 실패한 계산의 대체 시도를 만들지 않는다."""
    started = time.monotonic()
    from rfad.application.pcb_compute import limits

    budget = {"timeout_seconds": limits(entry["settings"])["max_wall_time_seconds"]}
    prepared = execute_phase(service, report, path, entry, "prepare", "solver.prepare", {
        "analysis_plan": {name: entry["analysis_plan"][name] for name in ("plan_id", "content_hash")}, "budget": budget}, subject["context"])
    solved = execute_phase(service, report, path, entry, "analysis", "job.submit", {
        "task_plan": {"kind": "em_analysis", "prepared_plan": {name: prepared["prepared_plan"][name] for name in ("prepared_plan_id", "content_hash")}, "execution_mode": "solve_and_postprocess"},
        "budget": budget}, subject["context"])
    opened = call(service, "result.open", {"artifact_id": solved["artifact_id"]}, subject["context"])
    roles = {item["role"]: item for item in opened["files"]}
    entry.update(status="completed", artifact_id=solved["artifact_id"], elapsed_seconds=time.monotonic() - started,
                 **{role: reference(roles[role]) for role in ("normalized_result", "radiation_result", "power_balance_result")})
    save_report(path, report)


def assess_available(study, runs):
    """! @brief 실패한 수준은 미확립으로 남기고 완료한 독립 축만 별도로 판정한다."""
    powers = {key: entry["power_balance"] for key, entry in runs.items() if entry["status"] == "completed"}
    if len(powers) == len(runs):
        return assess(study, powers)
    axes = {}
    for axis in sorted({case["axis"] for case in study["cases"]}):
        cases = [case for case in study["cases"] if case["axis"] == axis]
        missing = [case["label"] for case in cases if canonical_hash(case["settings"]) not in powers]
        if missing:
            axes[axis] = {"status": "not_established", "reason": "native_cases_not_completed", "missing_cases": missing,
                          "minimum_levels_met": False, "comparisons": []}
        else:
            axes[axis] = assess({**study, "cases": cases}, powers)["axes"][axis]
    return {"schema": "rfad.pcb-loss-study-assessment/0.1", "study_hash": canonical_hash(study), "axes": axes,
            "status": "not_established", "individual_loss_stability": "not_established", "full_energy_closure": "not_established",
            "scope": "tested_settings_only_not_continuum_accuracy", "physics_validated": False,
            "fabrication_validated": False, "measurement_validated": False}

"""! @brief 손실 연구의 격자/임계 구간/종료/곡선 단일 변화 축을 검사한다."""

from copy import deepcopy
import math

from rfad.application.canonical import canonical_hash
from rfad.application.pcb_geometry import fail, shape_polygons
from rfad.application.pcb_loss_convergence import assess_losses, validate_profile
from rfad.application.pcb_mesh import mesh_lines


AXIS_FIELDS = {"mesh": "grid_mm", "local_mesh": "feature_subdivisions", "termination": "end_criterion", "curve": "curve_tolerance_mm"}


def validate_study(study):
    """! @brief native 실행 전에 축별 세 수준 이상과 명시적 손실 기준을 요구한다."""
    if type(study) is not dict or study.get("schema") != "rfad.pcb-loss-study/0.1":
        fail("E_SCHEMA", "독립 손실 정밀도 연구 manifest가 필요합니다.")
    validate_profile(study.get("acceptance_profile"))
    cases = study.get("cases")
    if type(cases) is not list or not 3 <= len(cases) <= 24:
        fail("E_RESOURCE", "손실 연구는 3~24개 비교 행을 지원합니다.")
    labels = set()
    for case in cases:
        if (type(case) is not dict or set(case) != {"label", "axis", "settings"}
                or type(case["label"]) is not str or not 1 <= len(case["label"]) <= 64
                or case["label"] in labels or case["axis"] not in AXIS_FIELDS):
            fail("E_SCHEMA", "손실 연구의 사례 식별/변화 축이 다릅니다.")
        from rfad.application.pcb_solver import validate_settings

        validate_settings(case["settings"])
        if "power_balance" not in case["settings"]:
            fail("E_SCHEMA", "독립 손실 기록 없이 손실 정밀도를 판정할 수 없습니다.")
        labels.add(case["label"])
    for axis in {case["axis"] for case in cases}:
        rows = [case for case in cases if case["axis"] == axis]
        if not study["acceptance_profile"]["minimum_levels"] <= len(rows) <= 6:
            fail("E_SCHEMA", "각 손실 변화 축에는 최소 수준 이상의 순서 있는 사례가 필요합니다.")
        for a, b in zip(rows, rows[1:]):
            changed_pair(a["settings"], b["settings"], axis)


def changed_pair(first, second, axis):
    """! @brief 여러 조건을 함께 바꾼 결과를 개별 축의 수렴으로 해석하지 않는다."""
    key = AXIS_FIELDS[axis]
    a, b = deepcopy(first), deepcopy(second)
    x, y = a.pop(key, 1 if axis == "local_mesh" else None), b.pop(key, 1 if axis == "local_mesh" else None)
    if a != b or x is None or y is None or (y <= x if axis == "local_mesh" else y >= x):
        fail("E_SCHEMA", "손실 연구는 해당 수치 조건 하나만 엄격히 세분화해야 합니다.")


def plan_guard(left, right, axis):
    """! @brief 동일 원본/설치와 PML/기록 면을 확인하고 실제 세분화 근거를 남긴다."""
    a, b = left["case"], right["case"]
    changed_pair(a["settings"], b["settings"], axis)
    if (left["snapshot"] != right["snapshot"] or left["source_semantics"] != right["source_semantics"]
            or left["runtime_identity"] != right["runtime_identity"] or left["normalization"] != right["normalization"]):
        fail("E_HASH", "손실 연구의 원본/재료/급전/정규화/설치가 다릅니다.")
    x, y = mesh_lines(a), mesh_lines(b)
    fixed = all([x[key][0], x[key][8], x[key][-9], x[key][-1]] == [y[key][0], y[key][8], y[key][-9], y[key][-1]] for key in "xyz")
    first, second = a["radiation_recording"], b["radiation_recording"]
    if not fixed or any(first[key] != second[key] for key in ("start_mm", "stop_mm", "center_m", "frequency_hz", "theta_deg", "phi_deg")):
        fail("E_GEOMETRY", "손실 연구는 실제 외곽/PML/방사 기록 면과 각도를 고정해야 합니다.")
    counts = [math.prod(map(len, lines.values())) for lines in (x, y)]
    if axis in {"mesh", "local_mesh"} and counts[1] <= counts[0]:
        fail("E_GEOMETRY", "손실 연구의 실제 격자점이 증가하지 않았습니다.")
    if axis in {"termination", "curve"} and x != y:
        fail("E_GEOMETRY", "종료/곡선 독립 비교는 실제 Yee 격자를 고정해야 합니다.")
    if axis == "curve" and canonical_hash([shape_polygons(shape, a["settings"]["curve_tolerance_mm"]) for shape in a["shapes"]]) == canonical_hash([shape_polygons(shape, b["settings"]["curve_tolerance_mm"]) for shape in b["shapes"]]):
        fail("E_GEOMETRY", "곡선 연구의 실제 native polygon이 세분화되지 않았습니다.")
    return {"same_snapshot_source_runtime": True, "fixed_pml_and_radiation_planes": True,
            "single_setting_changed": True, "actual_grid_points": counts, "passed": True}


def assess(study, powers):
    """! @brief 각 변화 축을 별도 판정하고 개별 성분의 실패와 실물 미검증을 보존한다."""
    axes = {}
    for axis in sorted({case["axis"] for case in study["cases"]}):
        cases = [case for case in study["cases"] if case["axis"] == axis]
        axes[axis] = assess_losses([powers[canonical_hash(case["settings"])] for case in cases], study["acceptance_profile"])
    stable = all(value["status"] == "passed" for value in axes.values())
    closed = all(value["full_energy_closure"] == "within_initial_numerical_budget" for value in powers.values())
    return {"schema": "rfad.pcb-loss-study-assessment/0.1", "study_hash": canonical_hash(study), "axes": axes,
            "individual_loss_stability": "passed" if stable else "not_established",
            "full_energy_closure": "within_initial_numerical_budget" if closed else "requires_review",
            "status": "passed" if stable and closed else "not_established",
            "scope": "tested_settings_only_not_continuum_accuracy", "physics_validated": False,
            "fabrication_validated": False, "measurement_validated": False}

"""! @brief 에너지 수지와 구분하여 개별 독립 손실의 설정별 안정성을 비교한다."""

import math

from rfad.application.pcb_geometry import fail


def initial_profile():
    """! @brief 실측 정확도가 아닌 사전 채택용 개별 손실 수치 예산을 반환한다."""
    return {"id": "independent-loss-initial/0.1", "minimum_levels": 3,
            "max_relative_delta": 0.02, "absolute_fraction_floor": 1e-5}


def validate_profile(profile):
    """! @brief 영에 가까운 손실의 명시적 절대 바닥과 상대 예산을 함께 고정한다."""
    if (type(profile) is not dict or set(profile) != {"id", "minimum_levels", "max_relative_delta", "absolute_fraction_floor"}
            or type(profile["id"]) is not str or not 1 <= len(profile["id"]) <= 120
            or type(profile["minimum_levels"]) is not int or not 3 <= profile["minimum_levels"] <= 6
            or any(type(profile[key]) not in (int, float) or not math.isfinite(profile[key]) for key in ("max_relative_delta", "absolute_fraction_floor"))
            or not 1e-4 <= profile["max_relative_delta"] <= 0.1 or not 1e-8 <= profile["absolute_fraction_floor"] <= 1e-3):
        fail("E_SCHEMA", "독립 손실 비교에는 최소 3수준과 유한한 상대/수용 전력 비율 예산이 필요합니다.")


def _fractions(result):
    """! @brief 동일 여기 크기에 의존하지 않는 수용 전력 정규화와 원본별 성분을 읽는다."""
    rows = []
    for row in result["frequencies"]:
        frequency = row["frequency_hz"]
        if (type(frequency) not in (int, float) or not math.isfinite(frequency) or frequency <= 0
                or rows and frequency <= rows[-1][0]):
            fail("E_HASH", "손실 비교의 직접 주파수는 양의 유한 증가 배열이어야 합니다.")
        accepted = row["accepted_power_w_s2"]
        if type(accepted) not in (int, float) or not math.isfinite(accepted) or accepted <= 0:
            fail("E_HASH", "손실 비교에는 양의 수용 전력이 필요합니다.")
        values = {key: row[key] / accepted for key in ("dielectric_loss_w_s2", "conductor_loss_w_s2")}
        for key in ("sheet_loss_w_s2", "via_loss_w_s2"):
            if key in row:
                values[key] = row[key] / accepted
        for key in ("sheet_components", "dielectric_components", "via_components"):
            for item in row.get(key, []):
                name = key + ":" + item["entity_id"]
                if name in values:
                    fail("E_HASH", "손실 비교에 원본 식별자가 중복됐습니다.")
                values[name] = item["loss_w_s2"] / accepted
        if any(not math.isfinite(value) for value in values.values()):
            fail("E_HASH", "손실 비교 성분은 유한해야 합니다.")
        rows.append((frequency, values))
    return rows


def compare_losses(left, right, profile):
    """! @brief 모든 직접 주파수와 원본별 성분을 비교하며 작은 음수도 합격으로 자르지 않는다."""
    validate_profile(profile)
    first, second = _fractions(left), _fractions(right)
    if (not first or len(first) != len(second) or any(a[0] != b[0] or a[1].keys() != b[1].keys() for a, b in zip(first, second))):
        fail("E_HASH", "손실 비교의 주파수 또는 재료/도체 분할이 다릅니다.")
    rows = []
    for (frequency, a), (_, b) in zip(first, second):
        for name in a:
            delta, scale = abs(a[name] - b[name]), max(abs(a[name]), abs(b[name]))
            tolerance = max(profile["absolute_fraction_floor"], profile["max_relative_delta"] * scale)
            rows.append({"frequency_hz": frequency, "component": name, "left_fraction": a[name], "right_fraction": b[name],
                         "absolute_fraction_delta": delta, "relative_delta": delta / scale if scale else 0.0,
                         "allowed_fraction_delta": tolerance, "status": "passed" if min(a[name], b[name]) >= 0 and delta <= tolerance else "not_established"})
    return {"status": "passed" if all(row["status"] == "passed" for row in rows) else "not_established", "components": rows}


def assess_losses(results, profile):
    """! @brief 최소 수준을 확인하고 마지막 인접 쌍을 판정하며 이전 실패를 보존한다."""
    validate_profile(profile)
    comparisons = [compare_losses(a, b, profile) for a, b in zip(results, results[1:])]
    enough = len(results) >= profile["minimum_levels"]
    return {"schema": "rfad.independent-loss-stability/0.1", "profile": profile,
            "minimum_levels_met": enough, "comparisons": comparisons,
            "status": comparisons[-1]["status"] if comparisons and enough else "not_established",
            "scope": "tested_settings_only_not_continuum_accuracy", "physics_validated": False,
            "fabrication_validated": False, "measurement_validated": False}
